-- AIM-AirBnB schema (MySQL 8 / MariaDB 10.4+). utf8mb4. Run via: php private/install.php
CREATE TABLE IF NOT EXISTS settings (k VARCHAR(64) NOT NULL PRIMARY KEY, v MEDIUMTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS properties (id VARCHAR(32) NOT NULL PRIMARY KEY, slug VARCHAR(190) NOT NULL UNIQUE, status VARCHAR(16) NOT NULL DEFAULT 'draft', created_at DATETIME NOT NULL, data MEDIUMTEXT NOT NULL, KEY idx_status (status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bookings (id VARCHAR(32) NOT NULL PRIMARY KEY, ref VARCHAR(16) NOT NULL UNIQUE, property_id VARCHAR(32) NOT NULL, check_in DATE NOT NULL, check_out DATE NOT NULL, status VARCHAR(24) NOT NULL, token VARCHAR(64) NOT NULL, hold_until DATETIME NULL, created_at DATETIME NOT NULL, data MEDIUMTEXT NOT NULL, KEY idx_prop_dates (property_id, check_in, check_out), KEY idx_status (status), KEY idx_hold (status, hold_until)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reviews (id VARCHAR(32) NOT NULL PRIMARY KEY, property_id VARCHAR(32) NOT NULL, booking_ref VARCHAR(16) NULL UNIQUE, status VARCHAR(16) NOT NULL, created_at DATETIME NOT NULL, data MEDIUMTEXT NOT NULL, KEY idx_prop (property_id, status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS offers (id VARCHAR(32) NOT NULL PRIMARY KEY, code VARCHAR(24) NOT NULL UNIQUE, data TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS enquiries (id VARCHAR(32) NOT NULL PRIMARY KEY, status VARCHAR(16) NOT NULL, created_at DATETIME NOT NULL, data TEXT NOT NULL, KEY idx_status (status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS activity (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, t DATETIME NOT NULL, actor VARCHAR(60) NOT NULL, text VARCHAR(400) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admins (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, pass_hash VARCHAR(255) NOT NULL, role VARCHAR(16) NOT NULL DEFAULT 'staff', created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS guest_notes (k VARCHAR(190) NOT NULL PRIMARY KEY, note TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS hits (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, ip VARCHAR(45) NOT NULL, bucket VARCHAR(24) NOT NULL, t INT NOT NULL, KEY idx_hits (ip, bucket, t)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mail_log (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, t DATETIME NOT NULL, to_addr VARCHAR(150) NOT NULL, subject VARCHAR(200) NOT NULL, ok TINYINT NOT NULL, info VARCHAR(400) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
